begin;
-- Corporate governance only. No grants to mutate public.deals or provider truth.
create table public.governance_settings (
 id boolean primary key default true check(id), paused boolean not null default true,
 mode text not null default 'DISABLED' check(mode in ('DISABLED','SHADOW','BOUNDED')),
 concurrency_limit integer not null default 2 check(concurrency_limit between 1 and 4),
 daily_budget integer not null default 100000 check(daily_budget between 1 and 10000000), updated_at timestamptz not null default now()
);
insert into public.governance_settings(id) values(true);
create table public.governance_agents (
 agent_id text primary key, charter jsonb not null, charter_hash text not null, enabled boolean not null default false,
 check(charter->>'agent_id'=agent_id),check(charter_hash=encode(sha256(convert_to(charter::text,'utf8')),'hex'))
);
create table public.governance_sources (
 source_id text primary key, sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),
 observed_at timestamptz not null, expires_at timestamptz not null, classification text not null check(classification in ('CORPORATE','PUBLIC')),
 basis text not null check(basis in ('VERIFIED_CANONICAL_METRIC','APPROVED_REFERENCE','AGENT_REPORT')), value numeric, unit text,
 approved_by uuid not null references auth.users(id), visibility text not null default 'FOUNDER' check(visibility in ('FOUNDER','OPERATIONS')),
 check(expires_at>observed_at),check(source_id ~ '^[A-Za-z0-9][A-Za-z0-9:_/.-]{2,199}$')
);
create table public.governance_decisions (
 id uuid primary key default gen_random_uuid(), payload jsonb not null, action_hash text not null,
 committee_id text not null check(committee_id in ('A','B','C','D','E')), created_by uuid not null references auth.users(id),
 idempotency_key uuid not null, created_at timestamptz not null default now(),unique(created_by,idempotency_key),
 check(action_hash=encode(sha256(convert_to(payload::text,'utf8')),'hex'))
);
create table public.governance_tasks (
 id uuid primary key default gen_random_uuid(), agent_id text not null references public.governance_agents(agent_id),
 charter_version integer not null, payload jsonb not null, action_hash text not null, permission integer not null check(permission between 0 and 2),
 parent_task_id uuid references public.governance_tasks(id), depth integer not null default 0 check(depth between 0 and 2), dependency_ids uuid[] not null default '{}',
 decision_id uuid references public.governance_decisions(id), source_ids text[] not null default '{}',
 visibility text not null check(visibility in ('FOUNDER','OPERATIONS')), created_by uuid not null references auth.users(id),idempotency_key uuid not null,
 status text not null default 'QUEUED' check(status in ('QUEUED','RUNNING','COMPLETED','VERIFIED','FAILED','UNKNOWN','DEAD_LETTER','CANCELLED')),
 attempt_count integer not null default 0,max_attempts integer not null check(max_attempts between 1 and 3),cost_limit integer not null check(cost_limit between 1 and 100000),
 cost_reserved integer not null default 0,cost_actual integer,claim_id uuid,timeout_at timestamptz,next_attempt_at timestamptz not null default now(),
 output jsonb,output_hash text,error_code text,verified_by uuid references auth.users(id),verification_task_id uuid references public.governance_tasks(id),
 created_at timestamptz not null default now(),completed_at timestamptz,unique(created_by,idempotency_key),
 check(action_hash=encode(sha256(convert_to(payload::text,'utf8')),'hex'))
);
create index governance_task_queue on public.governance_tasks(status,next_attempt_at,created_at,id);
create index governance_tasks_parent on public.governance_tasks(parent_task_id);
create table public.governance_attempts (
 claim_id uuid primary key,task_id uuid not null references public.governance_tasks(id),reservation integer not null check(reservation>=0),actual integer,
 created_at timestamptz not null default now(),finished_at timestamptz,error_code text,provider_usage jsonb not null default '{}'
);
create index governance_attempt_budget on public.governance_attempts(created_at);
create table public.governance_approvals (
 id uuid primary key default gen_random_uuid(),task_id uuid not null references public.governance_tasks(id),action_hash text not null,
 actor_id uuid not null references auth.users(id),reason text not null,expires_at timestamptz not null,created_at timestamptz not null default now(),
 consumed_at timestamptz,revoked_at timestamptz
);
create index governance_approval_task on public.governance_approvals(task_id,expires_at);
create table public.governance_holds (
 id uuid primary key default gen_random_uuid(),decision_id uuid references public.governance_decisions(id),reason text not null,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),cleared_at timestamptz,cleared_by uuid references auth.users(id),clear_reason text
);
create table public.governance_opinions (
 id uuid primary key default gen_random_uuid(),decision_id uuid not null references public.governance_decisions(id),agent_id text not null references public.governance_agents(agent_id),
 task_id uuid not null references public.governance_tasks(id),stance text not null check(stance in ('FOR','AGAINST','DISSENT')),created_at timestamptz not null default now(),unique(decision_id,agent_id,task_id)
);
create table public.governance_packets (
 id uuid primary key default gen_random_uuid(),task_id uuid not null unique references public.governance_tasks(id),period text not null check(period in ('daily','weekly','monthly','quarterly')),
 report_ids uuid[] not null,payload jsonb not null,created_at timestamptz not null default now(),delivery_state text not null default 'INTERNAL_PUBLISHED' check(delivery_state='INTERNAL_PUBLISHED')
);
create table public.governance_outcomes (
 id uuid primary key default gen_random_uuid(),forecast_id text not null,task_id uuid not null references public.governance_tasks(id),
 actual numeric not null,unit text not null,source_id text not null references public.governance_sources(source_id),recorded_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),unique(task_id,forecast_id)
);
create table public.governance_schedules (
 period text primary key check(period in ('daily','weekly','monthly','quarterly')),enabled boolean not null default false,
 actor_id uuid references auth.users(id),last_period timestamptz,updated_at timestamptz not null default now()
);
insert into public.governance_schedules(period) values('daily'),('weekly'),('monthly'),('quarterly');
create or replace function public.governance_require_actor(p_actor uuid,p_founder boolean default false) returns text language plpgsql security definer set search_path='' as $$
declare r text;
begin
 select u.raw_app_meta_data->>'role' into r from auth.users u where u.id=p_actor and coalesce(u.raw_app_meta_data->>'disabled','false')<>'true' and (u.banned_until is null or u.banned_until<=now());
 if r is null or (p_founder and r not in ('founder','founder_admin')) or (not p_founder and r not in ('founder','founder_admin','admin_operator','ops_manager')) then raise exception using errcode='42501',message='GOVERNANCE_FORBIDDEN'; end if;return r;
end $$;
create or replace function public.governance_audit(p_actor uuid,p_event text,p_resource text,p_metadata jsonb) returns void language sql security definer set search_path='' as $$
 insert into public.audit_events(actor_id,event_type,route,metadata) values(p_actor,'AI_GOV_'||p_event,p_resource,p_metadata)
$$;
create or replace function public.governance_decision_ready(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.governance_decisions d where d.id=p_id and jsonb_array_length(d.payload->'evidence_missing')=0
 and not exists(select 1 from jsonb_array_elements_text(d.payload->'source_ids') ref where not exists(select 1 from public.governance_sources src where src.source_id=ref and src.observed_at<=now() and src.expires_at>now()))
 and not exists(select 1 from unnest(case d.committee_id when 'A' then array['D04','D05','D10'] when 'B' then case when d.payload->>'risk'='LOW' then array['D06','D07','D08'] else array['D06','D07','D08','D05'] end when 'C' then array['D03','D11','D05'] when 'D' then array['D08','D09','D12','D11'] else array['D01','D02','D04','D06','D09','D10'] end) member
 where not exists(select 1 from public.governance_opinions o join public.governance_tasks t on t.id=o.task_id join public.governance_sources source on source.source_id='report:'||t.id::text where o.decision_id=d.id and o.agent_id=member and t.status='VERIFIED' and source.expires_at>now())))
$$;
revoke all on function public.governance_decision_ready(uuid) from public,anon,authenticated;
create or replace function public.governance_command(p_actor uuid,p_operation text,p_body jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare r text;agent public.governance_agents%rowtype;t public.governance_tasks%rowtype;parent public.governance_tasks%rowtype;d public.governance_decisions%rowtype;
 result_id uuid;h text;tool text;lvl integer;deps uuid[];refs text[];members text[];category text;committee text;rec record;
begin
 r:=public.governance_require_actor(p_actor,p_operation not in ('task','pause','hold'));
 perform 1 from public.governance_settings where id=true for update;
 if p_operation='task' then
   select * into agent from public.governance_agents where agent_id=p_body->>'agent_id';
   tool:=p_body->>'tool_id';lvl:=case tool when 'read_board_evidence' then 0 when 'draft_report' then 1 when 'draft_recommendation' then 1 when 'publish_internal_brief' then 2 else 99 end;
   if agent.agent_id is null or not (agent.charter->'allowed_tool_ids' ? tool) or (agent.charter->'denied_tool_ids' ? tool) or lvl>(agent.charter->>'maximum_permission_level')::int then raise exception 'TOOL_NOT_AUTHORIZED';end if;
   if r not in ('founder','founder_admin') and (p_body->>'visibility' is distinct from 'OPERATIONS' or lvl>1 or p_body->>'decision_id' is not null) then raise exception using errcode='42501',message='GOVERNANCE_SCOPE_DENIED';end if;
   if length(p_body->>'title') not between 10 and 200 or (p_body->>'cost_limit')::int not between 1 and least(100000,(agent.charter->>'cost_budget')::int) then raise exception 'INVALID_TASK_BUDGET_OR_TITLE';end if;
   select coalesce(array_agg(x::uuid),'{}') into deps from jsonb_array_elements_text(p_body->'dependency_ids') x;
   select coalesce(array_agg(x),'{}') into refs from jsonb_array_elements_text(p_body->'source_ids') x;
   if cardinality(deps)>20 or cardinality(refs)>50 then raise exception 'TASK_SCOPE_TOO_LARGE';end if;
   if exists(select 1 from unnest(deps) x where not exists(select 1 from public.governance_tasks q where q.id=x and (r in ('founder','founder_admin') or q.visibility='OPERATIONS'))) then raise exception 'DEPENDENCY_NOT_FOUND_OR_FORBIDDEN';end if;
   if exists(select 1 from unnest(refs) x where not exists(select 1 from public.governance_sources s where s.source_id=x and s.expires_at>now() and s.observed_at<=now() and (r in ('founder','founder_admin') or s.visibility='OPERATIONS'))) then raise exception 'SOURCE_MISSING_STALE_OR_FORBIDDEN';end if;
   if p_body->>'parent_task_id' is not null then
     select * into parent from public.governance_tasks where id=(p_body->>'parent_task_id')::uuid;
     if not found or parent.depth>=2 or lvl>parent.permission or not refs<@parent.source_ids or (parent.visibility='FOUNDER' and p_body->>'visibility'='OPERATIONS') or (r not in ('founder','founder_admin') and parent.visibility<>'OPERATIONS') then raise exception 'DELEGATION_CEILING';end if;
   end if;
   select * into t from public.governance_tasks where created_by=p_actor and idempotency_key=(p_body->>'idempotency_key')::uuid;
   if found then if t.payload<>p_body then raise exception 'IDEMPOTENCY_CONFLICT';end if;return to_jsonb(t);end if;
   if lvl=2 and p_body->>'decision_id' is null then raise exception 'MATERIAL_DECISION_REQUIRED';end if;
   insert into public.governance_tasks(agent_id,charter_version,payload,action_hash,permission,parent_task_id,depth,dependency_ids,decision_id,source_ids,visibility,created_by,idempotency_key,max_attempts,cost_limit)
   values(agent.agent_id,(agent.charter->>'charter_version')::int,p_body,encode(sha256(convert_to(p_body::text,'utf8')),'hex'),lvl,parent.id,coalesce(parent.depth+1,0),deps,(p_body->>'decision_id')::uuid,refs,p_body->>'visibility',p_actor,(p_body->>'idempotency_key')::uuid,(agent.charter->>'max_retries')::int+1,(p_body->>'cost_limit')::int) returning id into result_id;
 elsif p_operation='decision' then
   category:=p_body->>'category';committee:=case when category in ('finance','capital') then 'A' when category in ('technology','security') then 'B' when category in ('legal','governance') then 'C' when category in ('product','revenue','global') then 'D' when category='strategy' then 'E' end;
   if committee is null or coalesce(p_body->>'risk','') not in ('LOW','MATERIAL','CRITICAL') or jsonb_typeof(p_body->'evidence_missing') is distinct from 'array' or p_body->>'responsible_director_id' !~ '^D(0[1-9]|1[0-2])$' then raise exception 'INVALID_DECISION';end if;
   select * into d from public.governance_decisions where created_by=p_actor and idempotency_key=(p_body->>'idempotency_key')::uuid;
   if found then if d.payload<>p_body then raise exception 'IDEMPOTENCY_CONFLICT';end if;return to_jsonb(d);end if;
   insert into public.governance_decisions(payload,action_hash,committee_id,created_by,idempotency_key) values(p_body,encode(sha256(convert_to(p_body::text,'utf8')),'hex'),committee,p_actor,(p_body->>'idempotency_key')::uuid) returning id into result_id;
 elsif p_operation='approve' then
   select * into t from public.governance_tasks where id=(p_body->>'task_id')::uuid for update;
   if not found or t.status<>'QUEUED' or t.action_hash is distinct from p_body->>'action_hash' then raise exception 'APPROVAL_TARGET_MISMATCH';end if;
   if length(trim(coalesce(p_body->>'reason',''))) not between 10 and 500 or (p_body->>'ttl_seconds')::int not between 30 and 3600 then raise exception 'APPROVAL_REASON_OR_TTL_REQUIRED';end if;
   if exists(select 1 from public.governance_holds where cleared_at is null and (decision_id is null or decision_id=t.decision_id)) then raise exception 'CRITICAL_HOLD';end if;
   if t.decision_id is not null then
     select * into d from public.governance_decisions where id=t.decision_id;
     if jsonb_array_length(d.payload->'evidence_missing')<>0 then raise exception 'MISSING_DECISION_EVIDENCE';end if;
     members:=case d.committee_id when 'A' then array['D04','D05','D10'] when 'B' then array['D06','D07','D08'] when 'C' then array['D03','D11','D05'] when 'D' then array['D08','D09','D12','D11'] else array['D01','D02','D04','D06','D09','D10'] end;
     if d.committee_id='B' and d.payload->>'risk'<>'LOW' then members:=array_append(members,'D05');end if;
     if exists(select 1 from unnest(members) member where not exists(select 1 from public.governance_opinions o join public.governance_tasks q on q.id=o.task_id where o.decision_id=d.id and o.agent_id=member and q.status='VERIFIED')) then raise exception 'COMMITTEE_CONSULTATION_REQUIRED';end if;
   end if;
   select id into result_id from public.governance_approvals where task_id=t.id and action_hash=t.action_hash and revoked_at is null and consumed_at is null and expires_at>now() order by created_at,id limit 1;
   if result_id is not null then return jsonb_build_object('id',result_id,'duplicate',true);end if;
   if t.permission=2 and not public.governance_decision_ready(t.decision_id) then raise exception 'COMMITTEE_CONSULTATION_REQUIRED';end if;
   insert into public.governance_approvals(task_id,action_hash,actor_id,reason,expires_at) values(t.id,t.action_hash,p_actor,p_body->>'reason',now()+make_interval(secs=>(p_body->>'ttl_seconds')::int)) returning id into result_id;
 elsif p_operation='source' then
   if p_body->>'source_id' like 'report:%' or p_body->>'source_id' like 'metric:%' then raise exception 'RESERVED_SOURCE_NAMESPACE';end if;
   if p_body->>'basis' is distinct from 'APPROVED_REFERENCE' then raise exception 'METRIC_SOURCE_REQUIRES_CANONICAL_READER';end if;
   insert into public.governance_sources(source_id,sha256,observed_at,expires_at,classification,basis,approved_by,visibility)
   values(p_body->>'source_id',p_body->>'sha256',(p_body->>'observed_at')::timestamptz,(p_body->>'expires_at')::timestamptz,p_body->>'classification','APPROVED_REFERENCE',p_actor,p_body->>'visibility');result_id:=null;
 elsif p_operation='pause' then
   if r not in ('founder','founder_admin') and p_body->>'paused' is distinct from 'true' then raise exception using errcode='42501',message='FOUNDER_REQUIRED';end if;
   if length(trim(coalesce(p_body->>'reason','')))<10 then raise exception 'REASON_REQUIRED';end if;
   if p_body->>'mode' not in ('DISABLED','SHADOW','BOUNDED') then raise exception 'INVALID_MODE';end if;
   update public.governance_settings set paused=(p_body->>'paused')::boolean,mode=p_body->>'mode',updated_at=now();
   if (p_body->>'paused')::boolean then update public.governance_tasks set status='UNKNOWN',error_code='FOUNDER_PAUSED',claim_id=null where status='RUNNING';end if;
 elsif p_operation='schedule' then
   if length(trim(coalesce(p_body->>'reason','')))<10 then raise exception 'REASON_REQUIRED';end if;
   update public.governance_schedules set enabled=(p_body->>'enabled')::boolean,actor_id=p_actor,updated_at=now() where period=p_body->>'period';if not found then raise exception 'INVALID_REPORTING_PERIOD';end if;
 elsif p_operation='agent' then
   update public.governance_agents set enabled=(p_body->>'enabled')::boolean where agent_id=p_body->>'agent_id';if not found then raise exception 'AGENT_NOT_FOUND';end if;
   if p_body->>'enabled'='false' then update public.governance_tasks set status='UNKNOWN',error_code='AGENT_DISABLED_UNKNOWN',claim_id=null where status='RUNNING' and agent_id=p_body->>'agent_id';end if;
 elsif p_operation='hold' then
   if length(trim(coalesce(p_body->>'reason','')))<10 then raise exception 'HOLD_REASON_REQUIRED';end if;
   insert into public.governance_holds(decision_id,reason,created_by) values((p_body->>'decision_id')::uuid,p_body->>'reason',p_actor) returning id into result_id;
 elsif p_operation='clear_hold' then
   if length(trim(coalesce(p_body->>'reason','')))<10 then raise exception 'HOLD_CLEAR_REASON_REQUIRED';end if;
   select * into t from public.governance_tasks where id=(p_body->>'verification_task_id')::uuid and status='VERIFIED' and agent_id='D05';if not found then raise exception 'INDEPENDENT_AUDIT_REQUIRED';end if;
   update public.governance_holds set cleared_at=now(),cleared_by=p_actor,clear_reason=p_body->>'reason' where id=(p_body->>'hold_id')::uuid and cleared_at is null and (decision_id is null or decision_id=t.decision_id);if not found then raise exception 'HOLD_NOT_FOUND';end if;
 elsif p_operation='verify' then
   select * into t from public.governance_tasks where id=(p_body->>'task_id')::uuid for update;
   if not found or t.status<>'COMPLETED' or t.output_hash is distinct from p_body->>'output_hash' then raise exception 'VERIFICATION_TARGET_MISMATCH';end if;
   if not exists(select 1 from public.governance_tasks v where v.id=(p_body->>'verification_task_id')::uuid and v.status in ('COMPLETED','VERIFIED') and v.agent_id<>t.agent_id and ('report:'||t.id::text)=any(v.source_ids)) then raise exception 'INDEPENDENT_VERIFIER_REQUIRED';end if;
   update public.governance_tasks set status='VERIFIED',verified_by=p_actor,verification_task_id=(p_body->>'verification_task_id')::uuid where id=t.id;result_id:=t.id;
 elsif p_operation='opinion' then
   select * into t from public.governance_tasks where id=(p_body->>'task_id')::uuid and status='VERIFIED';
   if not found or t.agent_id !~ '^D(0[1-9]|1[0-2])$' or t.decision_id is null then raise exception 'VERIFIED_DIRECTOR_REPORT_REQUIRED';end if;
   insert into public.governance_opinions(decision_id,agent_id,task_id,stance) values(t.decision_id,t.agent_id,t.id,p_body->>'stance') on conflict do nothing returning id into result_id;
 elsif p_operation='outcome' then
   select * into t from public.governance_tasks where id=(p_body->>'task_id')::uuid and status='VERIFIED';
   if not found then raise exception 'VERIFIED_FORECAST_REQUIRED';end if;
   if not exists(select 1 from jsonb_array_elements(t.output->'forecasts') f join public.governance_sources src on src.source_id=p_body->>'source_id' where f->>'forecast_id'=p_body->>'forecast_id' and (f->>'due_at')::timestamptz<=now() and src.observed_at>=(f->>'due_at')::timestamptz and src.expires_at>now() and src.basis='VERIFIED_CANONICAL_METRIC' and src.value is not null and src.unit=f->>'unit') then raise exception 'CLOSED_ACTUAL_EVIDENCE_REQUIRED';end if;
   insert into public.governance_outcomes(forecast_id,task_id,actual,unit,source_id,recorded_by) select p_body->>'forecast_id',t.id,value,unit,source_id,p_actor from public.governance_sources where source_id=p_body->>'source_id' returning id into result_id;
 elsif p_operation='retry' then
   update public.governance_tasks set status='QUEUED',error_code=null,next_attempt_at=now()+make_interval(secs=>least(300,5*(2^attempt_count)::int)) where id=(p_body->>'task_id')::uuid and status='FAILED' and attempt_count<max_attempts returning id into result_id;
   if not found then raise exception 'RETRY_NOT_SAFE';end if;
 elsif p_operation='compensate' then
   if length(trim(coalesce(p_body->>'reason','')))<10 then raise exception 'COMPENSATION_REASON_REQUIRED';end if;
   update public.governance_tasks set status='CANCELLED',error_code='HUMAN_WITHDRAWN_EVIDENCE_RETAINED' where id=(p_body->>'task_id')::uuid and status in ('COMPLETED','VERIFIED') returning id into result_id;
   if not found then raise exception 'COMPENSATION_NOT_SAFE';end if;
 elsif p_operation='cancel' then
   update public.governance_tasks set status='CANCELLED',claim_id=null,error_code='HUMAN_CANCELLED' where id=(p_body->>'task_id')::uuid and status in ('QUEUED','FAILED') returning id into result_id;
   if not found then raise exception 'CANCELLATION_NOT_SAFE';end if;
 elsif p_operation='revoke' then
   update public.governance_approvals set revoked_at=now() where id=(p_body->>'approval_id')::uuid and consumed_at is null and revoked_at is null returning id into result_id;
   if not found then raise exception 'APPROVAL_ALREADY_CONSUMED_OR_REVOKED';end if;
 else raise exception 'UNKNOWN_GOVERNANCE_OPERATION';end if;
 perform public.governance_audit(p_actor,upper(p_operation),coalesce(result_id::text,'settings'),jsonb_build_object('operation',p_operation,'target',coalesce(result_id::text,p_body->>'source_id'),'reason',p_body->>'reason'));
 return jsonb_build_object('id',result_id,'recorded',true);
end $$;
create or replace function public.governance_claim(p_reservation integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.governance_settings%rowtype;t public.governance_tasks%rowtype;a public.governance_agents%rowtype;approval uuid;reserved integer;
begin
 select * into s from public.governance_settings where id=true for update;
 if s.paused or s.mode='DISABLED' then return jsonb_build_object('status','PAUSED');end if;
 update public.governance_tasks set status='UNKNOWN',error_code='TIMEOUT_OUTCOME_UNKNOWN',claim_id=null where status='RUNNING' and timeout_at<=now();
 if (select count(*) from public.governance_tasks where status='RUNNING')>=s.concurrency_limit then return jsonb_build_object('status','CONCURRENCY_LIMIT');end if;
 for t in select q.* from public.governance_tasks q join public.governance_agents agent on agent.agent_id=q.agent_id
 where q.status='QUEUED' and q.next_attempt_at<=now() and q.attempt_count<q.max_attempts and agent.enabled
 and (agent.charter->>'charter_version')::int=q.charter_version
 and not exists(select 1 from public.governance_tasks running where running.agent_id=q.agent_id and running.status='RUNNING')
 and not exists(select 1 from unnest(q.dependency_ids) dep where not exists(select 1 from public.governance_tasks completed where completed.id=dep and completed.status='VERIFIED'))
 and ((q.permission=0 and q.agent_id in ('D05','D07')) or not exists(select 1 from public.governance_holds h where h.cleared_at is null and (h.decision_id is null or h.decision_id=q.decision_id)))
 order by q.created_at,q.id for update of q skip locked loop
   if exists(select 1 from unnest(t.source_ids) ref where (ref like 'report:%' and not exists(select 1 from public.governance_tasks producer where 'report:'||producer.id::text=ref and producer.status in ('COMPLETED','VERIFIED'))) or not exists(select 1 from public.governance_sources src where src.source_id=ref and src.expires_at>now() and src.observed_at<=now())) then
     update public.governance_tasks set status='FAILED',error_code='SOURCE_EXPIRED' where id=t.id;continue;
   end if;
   if t.permission=2 then
     if not public.governance_decision_ready(t.decision_id) then update public.governance_tasks set error_code='DECISION_REVIEW_REQUIRED' where id=t.id;continue;end if;
     if s.mode<>'BOUNDED' then continue;end if;
     select id into approval from public.governance_approvals where task_id=t.id and action_hash=t.action_hash and consumed_at is null and revoked_at is null and expires_at>now() order by created_at,id limit 1 for update;
     if approval is null then continue;end if;
   end if;
   reserved:=case when t.permission=0 or t.agent_id='B13' or t.payload->>'tool_id'='publish_internal_brief' then 0 else p_reservation end;
   if reserved is null then update public.governance_tasks set error_code='MODEL_UNCONFIGURED' where id=t.id;continue;end if;
   if reserved<0 or reserved>t.cost_limit or reserved+t.cost_reserved>t.cost_limit then update public.governance_tasks set status='DEAD_LETTER',error_code='TASK_BUDGET_EXHAUSTED' where id=t.id;continue;end if;
   if (select coalesce(sum(reservation),0) from public.governance_attempts where created_at>=date_trunc('day',now()))+reserved>s.daily_budget then return jsonb_build_object('status','DAILY_BUDGET');end if;
   if approval is not null then update public.governance_approvals set consumed_at=now() where id=approval;end if;
   select * into a from public.governance_agents where agent_id=t.agent_id;
   update public.governance_tasks set status='RUNNING',claim_id=gen_random_uuid(),attempt_count=attempt_count+1,cost_reserved=cost_reserved+reserved,timeout_at=now()+make_interval(secs=>(a.charter->>'timeout')::int) where id=t.id returning * into t;
   insert into public.governance_attempts(claim_id,task_id,reservation) values(t.claim_id,t.id,reserved);
   perform public.governance_audit(null,'CLAIM',t.id::text,jsonb_build_object('agent_id',t.agent_id,'attempt',t.attempt_count,'reservation',reserved,'claim_id',t.claim_id));
   return to_jsonb(t)||jsonb_build_object('reservation',reserved);
 end loop;
 return jsonb_build_object('status','IDLE');
end $$;
create or replace function public.governance_finish(p_task uuid,p_claim uuid,p_output jsonb,p_error text,p_cost integer,p_usage jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare t public.governance_tasks%rowtype;paused boolean;h text;
begin
 if jsonb_typeof(p_usage) is distinct from 'object' or p_usage - array['provider','model','message_id','input_tokens','output_tokens'] <> '{}'::jsonb or length(p_usage::text)>1000 then raise exception 'INVALID_PROVIDER_USAGE';end if;
 select s.paused into paused from public.governance_settings s where id=true for update;
 select * into t from public.governance_tasks where id=p_task for update;
 if not found or t.status<>'RUNNING' or t.claim_id is distinct from p_claim then raise exception 'CLAIM_NOT_CURRENT';end if;
 if paused or t.timeout_at<=now() or (not(t.permission=0 and t.agent_id in ('D05','D07')) and exists(select 1 from public.governance_holds where cleared_at is null and (decision_id is null or decision_id=t.decision_id))) then p_error:='EXECUTION_INTERRUPTED_UNKNOWN';end if;
 if p_cost is null or p_cost<0 or p_cost>(select reservation from public.governance_attempts where claim_id=p_claim) then p_error:=coalesce(p_error,'COST_OUTCOME_UNKNOWN');if p_error not like '%UNKNOWN%' then p_error:='COST_OUTCOME_UNKNOWN';end if;end if;
 if p_error is not null then
   update public.governance_tasks set status=case when p_error like '%UNKNOWN%' then 'UNKNOWN' when attempt_count>=max_attempts then 'DEAD_LETTER' else 'FAILED' end,error_code=left(p_error,100),claim_id=null,cost_actual=case when p_cost is not null and p_cost>=0 and p_cost<=(select reservation from public.governance_attempts where claim_id=p_claim) then coalesce(cost_actual,0)+p_cost else cost_actual end where id=t.id;
 else
   if t.payload->>'tool_id'='publish_internal_brief' and exists(select 1 from unnest(t.source_ids) ref where ref not like 'report:%' or not exists(select 1 from public.governance_tasks producer where 'report:'||producer.id::text=ref and producer.status='VERIFIED')) then raise exception 'VERIFIED_PACKET_REPORTS_REQUIRED';end if;
   if jsonb_typeof(p_output)<>'object' or p_output->>'schema_version'<>'1' or length(p_output::text)>30000 or p_output - array['schema_version','summary','source_ids','claims','dissent','risks','missing_evidence','forecasts']<>'{}'::jsonb then raise exception 'INVALID_REPORT';end if;
   if exists(select 1 from jsonb_array_elements_text(p_output->'source_ids') src where not src=any(t.source_ids)) then raise exception 'UNSCOPED_REPORT';end if;
   h:=encode(sha256(convert_to(p_output::text,'utf8')),'hex');
   update public.governance_tasks set status='COMPLETED',output=p_output,output_hash=h,cost_actual=coalesce(cost_actual,0)+p_cost,completed_at=now(),claim_id=null where id=t.id;
   insert into public.governance_sources(source_id,sha256,observed_at,expires_at,classification,basis,approved_by,visibility)
   values('report:'||t.id::text,h,now(),now()+interval '30 days','CORPORATE','AGENT_REPORT',t.created_by,t.visibility);
   if t.payload->>'tool_id'='publish_internal_brief' then
     insert into public.governance_packets(task_id,period,report_ids,payload) values(t.id,coalesce(t.payload->>'period','daily'),array(select substring(x from 8)::uuid from unnest(t.source_ids) x where x like 'report:%'),p_output);
   end if;
 end if;
 update public.governance_attempts set actual=case when p_cost>=0 then p_cost else null end,finished_at=now(),error_code=p_error,provider_usage=p_usage where claim_id=p_claim;
 perform public.governance_audit(null,case when p_error is null then 'REPORT_COMPLETED' else 'TASK_FAILED' end,t.id::text,jsonb_build_object('agent_id',t.agent_id,'output_hash',h,'error_code',p_error));
 return jsonb_build_object('task_id',t.id,'recorded',true,'output_hash',h);
end $$;
-- Finance is an aggregate over canonical settlement facts, never an agent-authored balance.
create or replace function public.governance_metrics(p_actor uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;rec record;ref text;observed timestamptz:=now();
begin
 perform public.governance_require_actor(p_actor,true);
 select jsonb_build_object('observed_at',now(),'basis','public.deals verified Wise settlement','settled_collections',coalesce((select jsonb_agg(x) from (
 select coalesce(currency,'USD') currency,count(*) matters,sum(amount_paid) amount from public.deals
 where payment_confirmed is true and payment_status='paid' and payment_settlement_status='cleared'
 and amount_due>0 and amount_paid>0 and amount_due::text not in ('NaN','Infinity','-Infinity') and amount_paid::text not in ('NaN','Infinity','-Infinity')
 and round(amount_paid*100)=round(amount_due*100) group by currency order by currency limit 100) x),'[]'::jsonb),
 'cash_balance',null,'recognized_revenue',null,'runway',null,'financial_status','BALANCE_AND_RECOGNIZED_REVENUE_NOT_VERIFIED') into result;
 for rec in select * from jsonb_to_recordset(result->'settled_collections') as x(currency text,matters bigint,amount numeric) loop
  ref:='metric:wise_collections:'||rec.currency||':'||gen_random_uuid()::text;
  insert into public.governance_sources(source_id,sha256,observed_at,expires_at,classification,basis,value,unit,approved_by) values(ref,encode(sha256(convert_to(jsonb_build_object('currency',rec.currency,'amount',rec.amount,'observed_at',observed)::text,'utf8')),'hex'),observed,observed+interval '2 hours','CORPORATE','VERIFIED_CANONICAL_METRIC',rec.amount,rec.currency,p_actor);
 end loop;
 perform public.governance_audit(p_actor,'METRICS_READ','canonical-settlement',jsonb_build_object('observed_at',observed));
 return result;
end $$;
create or replace function public.governance_read_allowed(visibility text) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from auth.users u where u.id=auth.uid() and coalesce(u.raw_app_meta_data->>'disabled','false')<>'true' and (u.banned_until is null or u.banned_until<=now()) and (u.raw_app_meta_data->>'role' in ('founder','founder_admin') or (visibility='OPERATIONS' and u.raw_app_meta_data->>'role' in ('admin_operator','ops_manager'))))
$$;
revoke all on function public.governance_read_allowed(text) from public,anon;
grant execute on function public.governance_read_allowed(text) to authenticated,service_role;
-- Direct client writes are denied, including for founders. All mutations use actor-checking RPCs.
do $$ declare name text;begin
 foreach name in array array['governance_schedules','governance_attempts','governance_settings','governance_agents','governance_sources','governance_decisions','governance_tasks','governance_approvals','governance_holds','governance_opinions','governance_packets','governance_outcomes'] loop
 execute format('alter table public.%I enable row level security',name);
 execute format('revoke all on public.%I from public,anon,authenticated',name);
 execute format('grant select on public.%I to authenticated',name);
 execute format('grant all on public.%I to service_role',name);
 if name in ('governance_sources','governance_tasks') then execute format('create policy governance_private_read on public.%I for select to authenticated using(public.governance_read_allowed(visibility))',name);
 elsif name='governance_agents' then execute format('create policy governance_private_read on public.%I for select to authenticated using(public.governance_read_allowed(''OPERATIONS''))',name);
 else execute format('create policy governance_private_read on public.%I for select to authenticated using(public.governance_read_allowed(''FOUNDER''))',name);end if;
 end loop;
end $$;
create or replace function public.governance_immutable() returns trigger language plpgsql set search_path='' as $$
begin raise exception using errcode='42501',message='GOVERNANCE_APPEND_ONLY';end $$;
create trigger governance_source_immutable before update or delete on public.governance_sources for each row execute function public.governance_immutable();
create trigger governance_decision_immutable before update or delete on public.governance_decisions for each row execute function public.governance_immutable();
create trigger governance_opinion_immutable before update or delete on public.governance_opinions for each row execute function public.governance_immutable();
create trigger governance_packet_immutable before update or delete on public.governance_packets for each row execute function public.governance_immutable();
create trigger governance_outcome_immutable before update or delete on public.governance_outcomes for each row execute function public.governance_immutable();
create or replace function public.governance_task_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if TG_OP='DELETE' or new.payload is distinct from old.payload or new.action_hash is distinct from old.action_hash or new.agent_id is distinct from old.agent_id or new.source_ids is distinct from old.source_ids or new.dependency_ids is distinct from old.dependency_ids or new.parent_task_id is distinct from old.parent_task_id or new.permission is distinct from old.permission or new.visibility is distinct from old.visibility or new.created_at is distinct from old.created_at or new.created_by is distinct from old.created_by or new.idempotency_key is distinct from old.idempotency_key or new.charter_version is distinct from old.charter_version or new.decision_id is distinct from old.decision_id or new.cost_limit is distinct from old.cost_limit or new.max_attempts is distinct from old.max_attempts or new.depth is distinct from old.depth then raise exception 'GOVERNANCE_TASK_IMMUTABLE';end if;
 if old.output is not null and (new.output is distinct from old.output or new.output_hash is distinct from old.output_hash) then raise exception 'GOVERNANCE_REPORT_IMMUTABLE';end if;return new;
end $$;
create trigger governance_task_immutable before update or delete on public.governance_tasks for each row execute function public.governance_task_guard();
create or replace function public.governance_approval_guard() returns trigger language plpgsql set search_path='' as $$
begin if TG_OP='DELETE' or new.task_id is distinct from old.task_id or new.action_hash is distinct from old.action_hash or new.actor_id is distinct from old.actor_id or new.reason is distinct from old.reason or new.created_at is distinct from old.created_at or new.expires_at is distinct from old.expires_at or (old.consumed_at is not null and new.consumed_at is distinct from old.consumed_at) or (old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at) then raise exception 'APPROVAL_BINDING_IMMUTABLE';end if;return new;end $$;
create trigger governance_approval_binding before update or delete on public.governance_approvals for each row execute function public.governance_approval_guard();
create or replace function public.governance_attempt_guard() returns trigger language plpgsql set search_path='' as $$
begin if TG_OP='DELETE' or new.claim_id is distinct from old.claim_id or new.task_id is distinct from old.task_id or new.reservation is distinct from old.reservation or new.created_at is distinct from old.created_at or (old.finished_at is not null and (new.actual is distinct from old.actual or new.finished_at is distinct from old.finished_at or new.provider_usage is distinct from old.provider_usage or new.error_code is distinct from old.error_code)) then raise exception 'ATTEMPT_EVIDENCE_IMMUTABLE';end if;return new;end $$;
create trigger governance_attempt_immutable before update or delete on public.governance_attempts for each row execute function public.governance_attempt_guard();
create or replace function public.governance_history_guard() returns trigger language plpgsql set search_path='' as $$
begin if old.event_type like 'AI_GOV_%' then raise exception 'GOVERNANCE_HISTORY_IMMUTABLE';end if;if TG_OP='DELETE' then return old;end if;return new;end $$;
create trigger governance_audit_immutable before update or delete on public.audit_events for each row execute function public.governance_history_guard();
-- No corporate history leaks through the legacy user-writable role fallback.
drop policy if exists audit_events_admin_read on public.audit_events;
create policy audit_events_admin_read on public.audit_events for select to authenticated using (
 public.governance_read_allowed(case when event_type like 'AI_GOV_%' then 'FOUNDER' else 'OPERATIONS' end)
);
revoke all on function public.governance_require_actor(uuid,boolean),public.governance_audit(uuid,text,text,jsonb),public.governance_command(uuid,text,jsonb),public.governance_claim(integer),public.governance_finish(uuid,uuid,jsonb,text,integer,jsonb),public.governance_metrics(uuid) from public,anon,authenticated;
grant execute on function public.governance_command(uuid,text,jsonb),public.governance_claim(integer),public.governance_finish(uuid,uuid,jsonb,text,integer,jsonb),public.governance_metrics(uuid) to service_role;

