create or replace function public.governance_enqueue_briefs() returns integer language plpgsql security definer set search_path='' as $$
declare schedule public.governance_schedules%rowtype;settings public.governance_settings%rowtype;start_at timestamptz;refs jsonb;total integer:=0;
begin
 select * into settings from public.governance_settings where id=true for update;
 if settings.paused or settings.mode='DISABLED' then return 0;end if;
 for schedule in select * from public.governance_schedules where enabled for update loop
  start_at:=date_trunc(case schedule.period when 'daily' then 'day' when 'weekly' then 'week' when 'monthly' then 'month' else 'quarter' end,now() at time zone 'America/New_York') at time zone 'America/New_York';
  if schedule.last_period is not null and schedule.last_period>=start_at then continue;end if;
  select coalesce(jsonb_agg('report:'||id::text),'[]'::jsonb) into refs from (select q.id from public.governance_tasks q join public.governance_sources src on src.source_id='report:'||q.id::text where q.status='VERIFIED' and q.created_at>=start_at and src.expires_at>now() order by q.created_at desc,q.id desc limit 50) selected;
  perform public.governance_command(schedule.actor_id,'task',jsonb_build_object('agent_id','B13','tool_id','draft_report','period',schedule.period,'title','Draft '||schedule.period||' internal board evidence packet','source_ids',refs,'parent_task_id',null,'dependency_ids','[]'::jsonb,'decision_id',null,'idempotency_key',md5('governance:'||schedule.period||':'||extract(epoch from start_at)::text)::uuid,'cost_limit',100000,'visibility','FOUNDER'));
  update public.governance_schedules set last_period=start_at where period=schedule.period;total:=total+1;
 end loop;
 perform public.governance_audit(null,'SCHEDULER_TICK','internal-briefs',jsonb_build_object('queued',total));return total;
end $$;
revoke all on function public.governance_enqueue_briefs() from public,anon,authenticated;
grant execute on function public.governance_enqueue_briefs() to service_role;
create table public.governance_charter_versions(agent_id text not null references public.governance_agents(agent_id),version integer not null,definition jsonb not null,sha256 text not null,created_at timestamptz not null default now(),primary key(agent_id,version));
insert into public.governance_charter_versions(agent_id,version,definition,sha256) select agent_id,(charter->>'charter_version')::int,charter,charter_hash from public.governance_agents;
alter table public.governance_tasks add constraint governance_charter_fk foreign key(agent_id,charter_version) references public.governance_charter_versions(agent_id,version);
alter table public.governance_charter_versions enable row level security;
revoke all on public.governance_charter_versions from public,anon,authenticated;
grant select on public.governance_charter_versions to authenticated;
grant all on public.governance_charter_versions to service_role;
create policy governance_charter_read on public.governance_charter_versions for select to authenticated using(public.governance_read_allowed('OPERATIONS'));
create trigger governance_charter_immutable before update or delete on public.governance_charter_versions for each row execute function public.governance_immutable();
create or replace function public.governance_charter_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if TG_OP='DELETE' or not exists(select 1 from public.governance_charter_versions v where v.agent_id=new.agent_id and v.version=(new.charter->>'charter_version')::int and v.sha256=new.charter_hash and v.definition=new.charter) then raise exception 'CHARTER_VERSION_REQUIRED';end if;return new;
end $$;
create trigger governance_agent_charter before update or delete on public.governance_agents for each row execute function public.governance_charter_guard();
grant insert on public.audit_events to service_role;

insert into public.retention_classes(class_id,canonical_name,description,duration_rule,start_event,start_timestamp_source,sensitivity,deletion_method,required_deletion_evidence,system_of_record,owner_subsystem,policy_status,deletion_eligible)
values('AI_CORPORATE_GOVERNANCE','AI corporate governance','Charters, corporate decisions, opinions, approvals, bounded tasks, reports, attempts and packets','REVIEW_REQUIRED','CORPORATE_RECORD_CLOSED','governance_tasks.completed_at','restricted','owner-approved retention review; no automated deletion','canonical deletion evidence and human authorization','governance_* / audit_events','governance_platform','review_required',false);
commit;
